javascript:
frappe.ready(function() {
    load_locations();
    load_documents();
});

function load_locations() {

    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Location",
            fields: ["name"],
            limit_page_length: 100
        },
        callback: function(r) {
            if (!r.message) return;

            r.message.forEach(function(loc) {
                $("#filter-location").append(
                    `<option value="${loc.name}">${loc.name}</option>`
                );
            });
        }
    });
}

function load_documents() {

    let filters = [];

    let status = $("#filter-status").val();
    let group = $("#filter-group").val();
    let location = $("#filter-location").val();

    if (status) filters.push(["status", "=", status]);
    if (group) filters.push(["group", "=", group]);
    if (location) filters.push(["location", "=", location]);

    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Document Registration",
            fields: [
                "name",
                "document_name",
                "department",
                "group",
                "year",
                "status",
                "location",
                "file_cover_image"
            ],
            filters: filters,
            order_by: "modified desc"
        },
        callback: function(r) {

            let html = "";

            if (!r.message || r.message.length === 0) {
                $("#document-list").html("<p>No documents found</p>");
                return;
            }

            r.message.forEach(function(doc) {

                let badge_class = "bg-success";
                if (doc.status === "Issued") badge_class = "bg-warning";
                if (doc.status === "Lost") badge_class = "bg-danger";

                let image = doc.file_cover_image 
                    ? doc.file_cover_image 
                    : "/assets/frappe/images/ui-empty-state.svg";

                html += `
                <div class="col-md-4 mb-4">
                    <div class="document-card">

                        <img src="${image}" class="document-image">

                        <div class="p-3">
                            <h5>${doc.document_name}</h5>

                            <p class="text-muted mb-1">
                                <strong>Location:</strong> ${doc.location}
                            </p>

                            <p class="text-muted mb-1">
                                <strong>Group:</strong> ${doc.group}
                            </p>

                            <span class="badge ${badge_class}">
                                ${doc.status}
                            </span>

                           <div class="mt-3">
                            <a href="/view-document?name=${doc.name}" 
                               style="
                                    display:block;
                                    background:linear-gradient(90deg,#1e3c72,#2a5298);
                                    color:#ffffff;
                                    padding:10px 14px;
                                    text-align:center;
                                    border-radius:8px;
                                    text-decoration:none;
                                    font-weight:700;
                                    font-size:15px;
                                    letter-spacing:0.5px;
                                    box-shadow:0 4px 8px rgba(0,0,0,0.15);
                                    transition:0.3s ease;">
                               VIEW DOCUMENT
                            </a>
                        </div>
</div>

                        </div>
                    </div>
                </div>
                `;
            });

            $("#document-list").html(html);
        }
    });
}

frappe.ready(function () {

    const urlParams = new URLSearchParams(window.location.search);
    const name = urlParams.get('name');

    if (!name) {
        $("#document-detail").html("<p>Document not found</p>");
        return;
    }

    frappe.call({
        method: "frappe.client.get",
        args: {
            doctype: "Document Registration",
            name: name
        },
        callback: function (r) {

            if (!r.message) return;

            let doc = r.message;

            let image_html = doc.file_cover_image
                ? `<img src="${doc.file_cover_image}" class="detail-image">`
                : "";

            let request_button = doc.status === "Available"
                ? `
                <button onclick="create_issue_request('${doc.name}')"
                    style="
                        display:block;
                        width:100%;
                        background:linear-gradient(90deg,#1e3c72,#2a5298);
                        color:#ffffff;
                        padding:10px 14px;
                        text-align:center;
                        border-radius:8px;
                        border:none;
                        font-weight:700;
                        font-size:15px;
                        letter-spacing:0.5px;
                        box-shadow:0 4px 8px rgba(0,0,0,0.15);
                        cursor:pointer;">
                    REQUEST DOCUMENT
                </button>
                `
                : `
                <div style="
                    width:100%;
                    background:#f8d7da;
                    color:#721c24;
                    padding:10px;
                    border-radius:8px;
                    font-weight:600;
                    text-align:center;">
                    Document Not Available
                </div>
                `;

            let html = `
            <div class="detail-card">

                <h2>${doc.document_name}</h2>
                <p><strong>ID:</strong> ${doc.name}</p>

                ${image_html}

                <div class="section-title">Basic Information</div>

                <div class="row mt-3">
                    <div class="col-md-6">
                        <p><span class="field-label">Document Type:</span> ${doc.document_type || "-"}</p>
                        <p><span class="field-label">Department:</span> ${doc.department || "-"}</p>
                        <p><span class="field-label">Group:</span> ${doc.group || "-"}</p>
                        <p><span class="field-label">Year:</span> ${doc.year || "-"}</p>
                    </div>

                    <div class="col-md-6">
                        <p><span class="field-label">Retention:</span> ${doc.retention_category || "-"}</p>
                        <p><span class="field-label">Sensitivity:</span> ${doc.sensitivity || "-"}</p>
                        <p><span class="field-label">Condition:</span> ${doc.condition_at_registration || "-"}</p>
                        <p><span class="field-label">Status:</span> ${doc.status || "-"}</p>
                    </div>
                </div>

                <div class="section-title">Storage Details</div>

                <div class="row mt-3">
                    <div class="col-md-6">
                        <p><span class="field-label">Location:</span> ${doc.location || "-"}</p>
                        <p><span class="field-label">Shelf:</span> ${doc.shelf || "-"}</p>
                    </div>

                    <div class="col-md-6">
                        <p><span class="field-label">Rack:</span> ${doc.rack || "-"}</p>
                        <p><span class="field-label">Expiry Date:</span> ${doc.expiry_date || "-"}</p>
                    </div>
                </div>

                <div class="section-title">Registration Details</div>

                <div class="row mt-3">
                    <div class="col-md-6">
                        <p><span class="field-label">Registered By:</span> ${doc.registered_by || "-"}</p>
                    </div>

                    <div class="col-md-6">
                        <p><span class="field-label">Registration Date:</span> ${doc.registration_date || "-"}</p>
                    </div>
                </div>

                <div class="mt-4">
                    ${request_button}
                </div>

            </div>
            `;

            $("#document-detail").html(html);
        }
    });

});


// ===============================
// CREATE ISSUE REQUEST FUNCTION
// ===============================

window.create_issue_request = function (document_name) {

    frappe.call({
        method: "frappe.client.get_value",
        args: {
            doctype: "Employee",
            filters: {
                user_id: frappe.session.user
            },
            fieldname: "name"
        },
        callback: function (r) {

            let employee = r.message ? r.message.name : "";

            let url = `/app/document-issue-request/new-document-issue-request-1?` +
                `document=${encodeURIComponent(document_name)}` +
                `&request_date=${frappe.datetime.get_today()}` +
                `&requested_by=${encodeURIComponent(employee)}`;

            window.location.href = url;

        }
    });

};
